// Verus program: bitwise XOR of two binary strings represented as Vec<char>
#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

spec fn is_bit(c: char) -> bool {
    c == '0' || c == '1'
}

spec fn xor_bit(x: char, y: char) -> char {
    if x == y { '0' } else { '1' }
}

fn string_xor(a: Vec<char>, b: Vec<char>) -> (out: Vec<char>)
    requires
        a.len() == b.len(),
        forall|i: int| 0 <= i < a.len() ==> is_bit(a[i]),
        forall|i: int| 0 <= i < b.len() ==> is_bit(b[i]),
    ensures
        out.len() == a.len(),
        forall|i: int| 0 <= i < out.len() ==> is_bit(out[i]),
        forall|i: int| 0 <= i < out.len() ==> out[i] == xor_bit(a[i], b[i]),
{
    let mut out: Vec<char> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            out.len() == i,
            i <= a.len(),
            a.len() == b.len(),
            forall|j: int| 0 <= j < a.len() ==> is_bit(a[j]),
            forall|j: int| 0 <= j < b.len() ==> is_bit(b[j]),
            forall|j: int| 0 <= j < i ==> out[j] == xor_bit(a[j], b[j]),
            forall|j: int| 0 <= j < i ==> is_bit(out[j]),
        decreases a.len() - i
    {
        let ai = a[i];
        let bi = b[i];

        // Prove the pushed character is a bit and matches xor_bit(ai, bi).
        assert(is_bit(ai));
        assert(is_bit(bi));

        let c = if ai == bi { '0' } else { '1' };

        assert(c == xor_bit(ai, bi));
        assert(is_bit(c));

        out.push(c);
        i += 1;
    }

    out
}

} // verus!